import { loadFont } from "@remotion/google-fonts/Montserrat";
import React from "react";
import { AbsoluteFill, Easing, interpolate, staticFile, useCurrentFrame } from "remotion";
import { VOZ_FIM, WARP } from "./warp";

// VENTUS · assessoria (método Linha de Fechamento). Motion vertical sobre a locução que o cliente mandou (59,3 s; sem as pausas, 54 s).
// As cenas estão escritas no tempo da locução original; WARP (tools/ventus_sem_pausas.py) converte o tempo do vídeo para ele.
// Identidade: azul-marinho #172942 e off-white #F8F6F4, as duas versões do logo que vieram. Tom sério e direto: sem mascote, sem confete.
// Pedido: bem dinâmico, na linha da referência (Avalom: texto grande central, uma ideia por vez, cartões) e com muita inversão de cor.
// A inversão é a linguagem do vídeo: cada cena é desenhada em função do tema (marinho ou claro) e SHOTS troca o tema nas palavras
// fortes, cada troca com uma cortina diferente. Destaque de palavra = etiqueta com as cores invertidas.
// Limpo: fundo liso, o texto entra e fica parado; o movimento contínuo fica nos objetos. Tempos = tempo da palavra na voz.

const { fontFamily: F } = loadFont("normal", { weights: ["600", "700", "800"], subsets: ["latin", "latin-ext"] });

export const VEN_FPS = 30;
export const VEN_FRAMES = Math.round((VOZ_FIM + 1.6) * VEN_FPS);

const NAVY = "#172942";
const PAPER = "#F8F6F4";
type Th = { bg: string; fg: string; dark: boolean };
const D: Th = { bg: NAVY, fg: PAPER, dark: true };
const L: Th = { bg: PAPER, fg: NAVY, dark: false };
const a = (th: Th, o: number) => (th.dark ? `rgba(248,246,244,${o})` : `rgba(23,41,66,${o})`);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.6));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, at: number, d = 0.45) => interpolate(t, [at, at + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, at: number, d = 0.42) => interpolate(t, [at, at + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a0: number, b: number) => interpolate(t, [a0, b], [0, 1], cl);
const io = (t: number, a0: number, b: number) => interpolate(t, [a0, b], [0, 1], { ...cl, easing: INOUT });
const rnd = (i: number) => { const x = Math.sin(i * 127.1 + 11.7) * 43758.5453; return x - Math.floor(x); };

type SP = { t: number; th: Th };
// Horizontal (1920x1080): as cenas continuam desenhadas no quadro vertical de 1080x1920; o texto vai para a metade esquerda
// (coluna de 722 px, centrada na altura) e HP leva cada grupo de objetos para a metade direita.
const Hz = React.createContext(false);
const HS = 0.86;
const HP: React.FC<{ v: [number, number]; h: [number, number]; s?: number; fade?: boolean; children: React.ReactNode }> = ({ v, h, s = 1, fade, children }) => {
  if (!React.useContext(Hz)) return <>{children}</>;
  const x0 = v[0] + (960 - h[0]) / s;                          // onde fica o meio da tela, no quadro vertical
  const m = fade ? `linear-gradient(to right, transparent ${x0.toFixed(0)}px, #000 ${(x0 + 150).toFixed(0)}px)` : undefined;
  return <div style={{ position: "absolute", left: 0, top: 0, width: 1080, height: 1920, transformOrigin: `${v[0]}px ${v[1]}px`, transform: `translate(${h[0] - v[0]}px, ${h[1] - v[1]}px) scale(${s})`, WebkitMaskImage: m, maskImage: m }}>{children}</div>;
};
const COL = 840;                                             // coluna central: margem lateral de 120 px

// ───────── texto: entra com impulso e fica parado; frases que se revezam ocupam o mesmo lugar ─────────
type Ln = [string, number, ("hl" | "soft")?];
const fit = (s: string, size: number, hl: boolean) => Math.min(size, COL / (s.length * 0.62 + (hl ? 0.56 : 0)));
const Say: React.FC<SP & { items: Ln[]; size: number; top: number; out?: number; lh?: number; hTop?: number }> = ({ t, th, items, size, top: vTop, out, lh = 1.16, hTop }) => {
  const hz = React.useContext(Hz);
  const o = out === undefined ? 0 : lin(t, out, out + 0.14);
  if (o >= 1) return null;
  const hBlock = items.reduce((n, it) => n + size * lh * (it[2] === "hl" ? 1.14 : 1), 0) * HS;
  const top = hz ? hTop ?? 540 - hBlock / 2 : vTop;
  return (
    <div style={{ position: "absolute", left: 120, width: COL, top, display: "flex", flexDirection: "column", alignItems: "center", opacity: 1 - o, filter: o > 0 ? `blur(${(o * 12).toFixed(1)}px)` : undefined, transform: hz ? `scale(${HS})` : undefined, transformOrigin: "0 0" }}>
      {items.map(([s, at, kind], i) => {
        const hl = kind === "hl";
        const fs = fit(s, size, hl);
        const e = pop(t, at, 0.4);
        const v = k(t, at, 0.28);
        return (
          <div key={i} style={{ height: size * lh * (hl ? 1.14 : 1), display: "flex", alignItems: "center", justifyContent: "center", opacity: Math.min(1, v * 2), transform: `scale(${(0.78 + 0.22 * e).toFixed(4)})`, filter: v < 1 ? `blur(${((1 - v) * 14).toFixed(1)}px)` : undefined }}>
            <span style={{ fontFamily: F, fontWeight: 800, fontSize: fs, letterSpacing: "-0.025em", lineHeight: 1, whiteSpace: "nowrap", color: hl ? th.bg : kind === "soft" ? a(th, 0.6) : th.fg, background: hl ? th.fg : undefined, padding: hl ? `${fs * 0.13}px ${fs * 0.28}px ${fs * 0.16}px` : 0, borderRadius: fs * 0.2 }}>{s}</span>
          </div>
        );
      })}
    </div>
  );
};
const Tag: React.FC<SP & { s: string; at: number; top: number; out?: number; hTop: number }> = ({ t, th, s, at, top: vTop, out, hTop }) => {
  const hz = React.useContext(Hz);
  const top = hz ? hTop : vTop;
  const e = k(t, at, 0.4);
  const o = out === undefined ? 0 : lin(t, out, out + 0.14);
  return (
    <div style={{ position: "absolute", left: 120, width: COL, top, textAlign: "center", fontFamily: F, fontWeight: 700, fontSize: 42, letterSpacing: `${(0.44 - 0.28 * e).toFixed(3)}em`, textTransform: "uppercase", color: a(th, 0.62), opacity: e * (1 - o), whiteSpace: "nowrap", transform: hz ? `scale(${HS})` : undefined, transformOrigin: "0 0" }}>{s}</div>
  );
};
// camada dos objetos: é ela que se move (câmera), o texto fica fora
const Obj: React.FC<{ s?: number; x?: number; y?: number; cy?: number; hcy?: number; hs?: number; fade?: boolean; children: React.ReactNode }> = ({ s = 1, x = 0, y = 0, cy = 1220, hcy, hs = 1, fade, children }) => (
  <HP v={[540, hcy ?? cy]} h={[1440, 540]} s={hs} fade={fade}><div style={{ position: "absolute", left: 0, top: 0, width: 1080, height: 1920, transform: `translate(${x.toFixed(1)}px, ${y.toFixed(1)}px) scale(${s.toFixed(4)})`, transformOrigin: `540px ${cy}px` }}>{children}</div></HP>
);
const At: React.FC<{ x: number; y: number; s?: number; r?: number; o?: number; children: React.ReactNode }> = ({ x, y, s = 1, r = 0, o = 1, children }) => (
  <div style={{ position: "absolute", left: x, top: y, width: 0, height: 0, opacity: o, transform: `scale(${s.toFixed(4)}) rotate(${r.toFixed(2)}deg)` }}>
    <div style={{ position: "absolute", transform: "translate(-50%, -50%)" }}>{children}</div>
  </div>
);
const lbl = (size: number, weight = 700): React.CSSProperties => ({ fontFamily: F, fontWeight: weight, fontSize: size, lineHeight: 1, whiteSpace: "nowrap", letterSpacing: "-0.01em" });

// ───────── peças ─────────
const Mark: React.FC<{ th: Th; file: string; w: number; h: number; color?: string }> = ({ th, file, w, h, color }) => (
  <div style={{ width: w, height: h, background: color ?? th.fg, WebkitMaskImage: `url(${staticFile(`ventus/${file}`)})`, maskImage: `url(${staticFile(`ventus/${file}`)})`, WebkitMaskSize: "100% 100%", maskSize: "100% 100%", WebkitMaskRepeat: "no-repeat", maskRepeat: "no-repeat" }} />
);
const Person: React.FC<{ size: number; fill: string; dashed?: string }> = ({ size, fill, dashed }) => (
  <svg width={size} height={size * 1.15} viewBox="0 0 60 69">
    <circle cx="30" cy="18" r="13" fill={dashed ? "none" : fill} stroke={dashed} strokeWidth={dashed ? 2.6 : 0} strokeDasharray="5 4" />
    <path d="M6 66 C6 46 17 39 30 39 C43 39 54 46 54 66 Z" fill={dashed ? "none" : fill} stroke={dashed} strokeWidth={dashed ? 2.6 : 0} strokeDasharray="5 4" />
  </svg>
);
// prédio simples: a "sua empresa" (genérico, sem marca)
const Building: React.FC<{ th: Th; size: number; p: number; ghost?: boolean }> = ({ th, size, p, ghost }) => (
  <svg width={size} height={size * 1.1} viewBox="0 0 200 220">
    <rect x="28" y="16" width="144" height="196" rx="12" fill={ghost ? "none" : th.fg} stroke={ghost ? a(th, 0.7) : "none"} strokeWidth="4" strokeDasharray="12 9" />
    {!ghost && Array.from({ length: 12 }).map((_, i) => {
      const e = Math.max(0, Math.min(1, p * 12 - i * 0.8));
      return <rect key={i} x={49 + (i % 3) * 37} y={36 + Math.floor(i / 3) * 34} width="28" height="22" rx="4" fill={th.bg} opacity={e} transform={`translate(0 ${(1 - e) * 8})`} />;
    })}
    {!ghost && <rect x="84" y="176" width="32" height="36" rx="4" fill={th.bg} />}
    <rect x="8" y="208" width="184" height="8" rx="4" fill={ghost ? a(th, 0.5) : th.fg} />
  </svg>
);
const Lens: React.FC<{ size: number; color: string }> = ({ size, color }) => (
  <svg width={size} height={size} viewBox="0 0 48 48" fill="none" stroke={color} strokeWidth="5" strokeLinecap="round"><circle cx="20" cy="20" r="13" /><path d="M30 30 L43 43" /></svg>
);
// barra de busca genérica, com o texto sendo digitado
const Search: React.FC<{ th: Th; text: string; p: number; t: number; w?: number }> = ({ th, text, p, t, w = COL }) => {
  const n = Math.round(Math.max(0, Math.min(1, p)) * text.length);
  const fs = Math.min(50, (w - 190) / (text.length * 0.56));
  return (
    <div style={{ width: w, height: 128, borderRadius: 64, background: th.fg, display: "flex", alignItems: "center", padding: "0 44px", gap: 26, boxSizing: "border-box", boxShadow: th.dark ? "0 30px 70px rgba(0,0,0,0.28)" : "0 30px 70px rgba(23,41,66,0.22)" }}>
      <Lens size={52} color={th.bg} />
      <span style={{ ...lbl(fs, 600), color: th.bg }}>{text.slice(0, n)}</span>
      <span style={{ width: 4, height: 54, marginLeft: -18, background: th.bg, opacity: p < 1 || Math.floor(t * 2.5) % 2 === 0 ? 1 : 0 }} />
    </div>
  );
};
const Chip: React.FC<{ th: Th; s: string; size?: number; solid?: boolean }> = ({ th, s, size = 40, solid = true }) => (
  <div style={{ ...lbl(size), color: solid ? th.bg : th.fg, background: solid ? th.fg : "transparent", border: solid ? undefined : `3px solid ${a(th, 0.5)}`, padding: `${size * 0.42}px ${size * 0.8}px`, borderRadius: size * 1.2 }}>{s}</div>
);
const Rings: React.FC<{ th: Th; t: number; at: number; n?: number; r0?: number; r1?: number; every?: number }> = ({ th, t, at, n = 3, r0 = 60, r1 = 620, every = 0.22 }) => (
  <>
    {Array.from({ length: n }).map((_, i) => {
      const p = lin(t, at + i * every, at + i * every + 1.1);
      if (p <= 0 || p >= 1) return null;
      const r = r0 + (r1 - r0) * OUT(p);
      return <div key={i} style={{ position: "absolute", left: -r, top: -r, width: r * 2, height: r * 2, borderRadius: "50%", border: `4px solid ${a(th, 0.5 * (1 - p))}`, boxSizing: "border-box" }} />;
    })}
  </>
);
// linha com quatro nós: a "linha de fechamento" (reaparece nos pilares)
const Line4: React.FC<{ th: Th; p: number; on: number; y: number; w?: number }> = ({ th, p, on, y, w = 720 }) => {
  const x0 = 540 - w / 2;
  return (
    <>
      <div style={{ position: "absolute", left: x0, top: y - 3, width: w, height: 6, borderRadius: 3, background: a(th, 0.22) }} />
      <div style={{ position: "absolute", left: x0, top: y - 3, width: w * p, height: 6, borderRadius: 3, background: th.fg }} />
      {[0, 1, 2, 3].map((i) => {
        const e = Math.max(0, Math.min(1, (p - i / 3) * 9 + 1));
        const lit = i < on;
        return (
          <At key={i} x={x0 + (w * i) / 3} y={y} s={0.4 + 0.6 * BACK(e) + (i === on - 1 ? 0.25 : 0)} o={e}>
            <div style={{ width: 44, height: 44, borderRadius: 22, background: lit ? th.fg : th.bg, border: `6px solid ${th.fg}`, boxSizing: "border-box" }} />
          </At>
        );
      })}
    </>
  );
};

// ───────── 1 · gancho (0–7,0): "Se você tem uma empresa de redução de parcelas de veículo, renegociação de dívidas" ─────────
const Car: React.FC<{ color: string; size: number }> = ({ color, size }) => (
  <svg width={size} height={size * 0.56} viewBox="0 0 160 90">
    <path d="M10 62 L24 34 Q30 22 46 22 L104 22 Q118 22 126 32 L140 52 Q154 55 154 68 L154 74 L10 74 Z" fill={color} />
    <circle cx="44" cy="74" r="14" fill={color} stroke="var(--bg)" strokeWidth="6" /><circle cx="118" cy="74" r="14" fill={color} stroke="var(--bg)" strokeWidth="6" />
  </svg>
);
const SHook: React.FC<SP> = ({ t, th }) => {
  const cam = 1 + 0.05 * lin(t, 0, 7) + 0.05 * punch(t);
  return (
    <>
      <Tag t={t} th={th} s="Você tem uma empresa de" at={0.45} top={330} hTop={285} />
      <Say t={t} th={th} top={430} size={128} out={2.0} items={[["Sua", 0.12], ["empresa", 1.18, "hl"]]} />
      <Say t={t} th={th} top={430} size={124} out={4.3} items={[["Redução", 2.1], ["de parcelas", 2.62], ["de veículo", 3.58, "hl"]]} />
      <Say t={t} th={th} top={430} size={118} items={[["Renegociação", 4.38], ["de dívidas", 5.78, "hl"]]} />
      <Obj s={cam} cy={1330}>
        {t < 2.3 && (
          <At x={540} y={1330} s={0.5 + 0.5 * pop(t, 0.05, 0.5) + 0.1 * lin(t, 0.4, 2.1)} o={1 - lin(t, 2.0, 2.12)}>
            <Building th={th} size={430} p={lin(t, 0.25, 1.6)} />
          </At>
        )}
        {t >= 2.0 && t < 4.5 && (
          <At x={540} y={1340} s={0.7 + 0.3 * pop(t, 2.08, 0.45)} o={k(t, 2.05, 0.2) * (1 - lin(t, 4.3, 4.42))}>
            <div style={{ width: 700, padding: "46px 50px 50px", borderRadius: 44, background: th.fg, boxSizing: "border-box", display: "flex", flexDirection: "column", gap: 30, ["--bg" as string]: th.fg }}>
              <div style={{ ...lbl(40), color: th.bg, opacity: 0.7 }}>Parcela</div>
              {[0, 1, 2].map((i) => {
                const w = interpolate(io(t, 2.35 + i * 0.22, 3.3 + i * 0.22), [0, 1], [100, 62 - i * 12]);
                return (
                  <div key={i} style={{ height: 56, borderRadius: 28, background: th.dark ? "rgba(23,41,66,0.14)" : "rgba(248,246,244,0.2)", position: "relative" }}>
                    <div style={{ position: "absolute", left: 0, top: 0, bottom: 0, width: `${w}%`, borderRadius: 28, background: th.bg }} />
                  </div>
                );
              })}
            </div>
            <div style={{ position: "absolute", right: -50, top: -90, ["--bg" as string]: th.bg, transform: `scale(${pop(t, 3.6, 0.4).toFixed(3)}) rotate(${(-8 + 8 * k(t, 3.6, 0.5)).toFixed(2)}deg)` }}>
              <div style={{ width: 250, height: 180, borderRadius: 40, background: th.bg, border: `6px solid ${th.fg}`, boxSizing: "border-box", display: "flex", alignItems: "center", justifyContent: "center", transform: `translateX(${(Math.sin(t * 9) * 3).toFixed(1)}px)` }}>
                <Car color={th.fg} size={170} />
              </div>
            </div>
          </At>
        )}
        {t >= 4.3 && (
          <At x={540} y={1350} s={0.7 + 0.3 * pop(t, 4.4, 0.45)} o={k(t, 4.38, 0.2)}>
            <div style={{ width: 560, padding: "48px 50px 56px", borderRadius: 44, background: th.fg, boxSizing: "border-box", display: "flex", flexDirection: "column", gap: 28 }}>
              <div style={{ ...lbl(40), color: th.bg, opacity: 0.7 }}>Dívida</div>
              {[100, 100, 70].map((w0, i) => (
                <div key={i} style={{ height: 34, borderRadius: 17, width: `${interpolate(io(t, 5.8 + i * 0.12, 6.6 + i * 0.12), [0, 1], [w0, w0 * 0.5])}%`, background: th.bg, opacity: i === 2 ? 0.55 : 1 }} />
              ))}
            </div>
            <div style={{ position: "absolute", right: -70, bottom: -70, width: 190, height: 190, borderRadius: 95, background: th.bg, border: `6px solid ${th.fg}`, boxSizing: "border-box", display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${pop(t, 4.75, 0.4).toFixed(3)})` }}>
              <svg width="110" height="110" viewBox="0 0 48 48" fill="none" stroke={th.fg} strokeWidth="4.5" strokeLinecap="round" strokeLinejoin="round" style={{ transform: `rotate(${(t * 150).toFixed(1)}deg)` }}>
                <path d="M40 24 A16 16 0 0 1 11 33" /><path d="M8 24 A16 16 0 0 1 37 15" /><path d="M37 6 L37 15 L28 15" /><path d="M11 42 L11 33 L20 33" />
              </svg>
            </div>
          </At>
        )}
      </Obj>
    </>
  );
};

// ───────── 2 · indicações (7,0–11,9) ─────────
const SRefer: React.FC<SP> = ({ t, th }) => {
  const xs = [213, 431, 649, 867];
  const tok = io(t, 8.2, 9.7);                               // a indicação anda devagar de uma pessoa para a outra
  return (
    <>
      <Say t={t} th={th} top={380} size={118} out={9.62} items={[["Até quando", 7.11], ["vai depender", 7.75], ["de indicações", 8.83, "hl"]]} />
      <Say t={t} th={th} top={380} size={118} items={[["para conquistar", 9.73], ["novos", 10.6], ["clientes?", 11.22, "hl"]]} />
      <Obj s={1 + 0.06 * lin(t, 7, 11.9) + 0.05 * punch(t)} x={interpolate(t, [7, 11.9], [18, -18], cl)} cy={1330}>
        <div style={{ position: "absolute", left: xs[0], top: 1327, width: (xs[3] - xs[0]) * k(t, 7.2, 0.8), height: 0, borderTop: `6px dashed ${a(th, 0.35)}` }} />
        {xs.map((x, i) => {
          const known = i < 2;
          const at = known ? 7.15 + i * 0.18 : [9.97, 10.6][i - 2];
          const arrived = i === 1 ? k(t, 9.6, 0.3) : i === 0 ? 1 : 0;
          return (
            <At key={i} x={x} y={1330} s={pop(t, at, 0.4) * (1 + (i === 1 ? 0.15 * Math.sin(Math.PI * lin(t, 9.6, 10.0)) : 0))}>
              <div style={{ width: 176, height: 176, borderRadius: 88, background: arrived > 0.5 ? th.fg : th.bg, border: known ? `6px solid ${th.fg}` : `6px dashed ${a(th, 0.55)}`, boxSizing: "border-box", display: "flex", alignItems: "center", justifyContent: "center" }}>
                {known ? <Person size={92} fill={arrived > 0.5 ? th.bg : th.fg} /> : <span style={{ ...lbl(96, 800), color: a(th, 0.6), transform: `translateY(${(Math.sin(t * 5 + i) * 5).toFixed(1)}px)` }}>?</span>}
              </div>
            </At>
          );
        })}
        <At x={xs[0] + (xs[1] - xs[0]) * tok} y={1330 - 150 - 26 * Math.sin(Math.PI * tok)} s={pop(t, 8.2, 0.35) * (1 - k(t, 9.7, 0.25))}>
          <Chip th={th} s="indicação" size={34} />
        </At>
      </Obj>
    </>
  );
};

// ───────── 3 · a espera (11,9–15,2) ─────────
const SWait: React.FC<SP> = ({ t, th }) => {
  const dots = ".".repeat(1 + (Math.floor(t * 3.2) % 3));
  return (
    <>
      <Say t={t} th={th} top={380} size={118} items={[["Enquanto você", 12.13], ["espera", 12.79, "hl"], ["uma indicação…", 13.9]]} />
      <Obj s={0.9 + 0.1 * pop(t, 11.95, 0.5) + 0.07 * lin(t, 12, 15.2) + 0.05 * punch(t)} cy={1360}>
        <At x={540} y={1300}>
          <div style={{ width: 430, height: 430, borderRadius: 215, border: `14px solid ${th.fg}`, boxSizing: "border-box", position: "relative" }}>
            {Array.from({ length: 12 }).map((_, i) => (
              <div key={i} style={{ position: "absolute", left: 201 - 4, top: 201 - 190, width: 8, height: i % 3 === 0 ? 34 : 18, borderRadius: 4, background: a(th, i % 3 === 0 ? 1 : 0.45), transformOrigin: "4px 190px", transform: `rotate(${i * 30}deg)` }} />
            ))}
            <div style={{ position: "absolute", left: 201 - 7, top: 201 - 150, width: 14, height: 160, borderRadius: 7, background: th.fg, transformOrigin: "7px 150px", transform: `rotate(${((t - 11.9) * 300).toFixed(1)}deg)` }} />
            <div style={{ position: "absolute", left: 201 - 8, top: 201 - 96, width: 16, height: 106, borderRadius: 8, background: th.fg, transformOrigin: "8px 96px", transform: `rotate(${(60 + (t - 11.9) * 25).toFixed(1)}deg)` }} />
            <div style={{ position: "absolute", left: 201 - 18, top: 201 - 18, width: 36, height: 36, borderRadius: 18, background: th.fg }} />
          </div>
        </At>
        <At x={540} y={1620} s={pop(t, 13.95, 0.4)}>
          <div style={{ ...lbl(40), color: th.bg, background: th.fg, padding: "22px 0", width: 470, borderRadius: 50, textAlign: "center" }}>
            <span>aguardando</span><span style={{ display: "inline-block", width: 44, textAlign: "left" }}>{dots}</span>
          </div>
        </At>
      </Obj>
    </>
  );
