// ───────── roteiro das inversões: [início, cena, tema, cortina] ─────────
type Wipe = "cut" | "diag" | "circle" | "split" | "up" | "side" | "chev" | "bars";
const SHOTS: [number, React.FC<SP>, Th, Wipe][] = [
  [0, SHook, D, "cut"], [0.45, SHook, L, "cut"], [1.16, SHook, D, "split"], [2.03, SHook, L, "diag"], [3.53, SHook, D, "up"], [4.33, SHook, L, "chev"], [5.74, SHook, D, "circle"], [6.4, SHook, L, "side"],
  [7, SRefer, D, "bars"], [8.78, SRefer, L, "side"], [9.68, SRefer, D, "diag"], [10.5, SRefer, L, "up"], [11.2, SRefer, D, "cut"],
  [11.9, SWait, L, "chev"], [12.79, SWait, D, "cut"], [13.85, SWait, L, "split"],
  [15.2, SSearch, D, "chev"], [16.25, SSearch, L, "cut"], [17.48, SSearch, D, "circle"], [18.86, SSearch, L, "diag"],
  [19.78, SQueries, D, "bars"], [21.6, SQueries, L, "side"], [22.55, SQueries, D, "cut"], [23.4, SQueries, L, "up"],
  [24.5, SReady, D, "circle"], [25.84, SReady, L, "cut"], [26.7, SReady, D, "side"],
  [27.7, SUnknown, L, "diag"], [29.17, SUnknown, D, "cut"],
  [29.9, SBrand, L, "up"], [30.72, SBrand, D, "split"], [31.72, SBrand, L, "chev"], [32.5, SBrand, D, "cut"],
  [33.2, SMethod, L, "bars"], [34.6, SMethod, D, "diag"], [35.66, SMethod, L, "cut"], [36.3, SMethod, D, "circle"],
  [37, SFour, L, "up"], [38.15, SFour, D, "cut"],
  [39.34, P1, L, "chev"],
  [40.29, P2, D, "side"],
  [41.69, P3, L, "circle"],
  [42.84, P4, D, "diag"],
  [44.05, SDemand, L, "bars"], [45, SDemand, D, "side"], [45.98, SDemand, L, "circle"], [47.2, SDemand, D, "cut"], [48.14, SDemand, L, "up"], [49.24, SDemand, D, "diag"],
  [50.6, SCta, L, "split"], [51.6, SCta, D, "up"], [52.44, SCta, L, "side"], [53.74, SCta, D, "chev"], [54.98, SCta, L, "circle"], [56.94, SCta, D, "diag"], [58.45, SCta, L, "cut"], [59.38, SCta, D, "up"],
];
const WD = 0.3;
const shotAt = (t: number) => { let i = 0; while (i + 1 < SHOTS.length && SHOTS[i + 1][0] <= t) i++; return i; };
// impulso curto dos objetos a cada inversão (o texto não recebe)
function punch(t: number) { const s = SHOTS[shotAt(t)][0]; return Math.exp(-(t - s) * 7); }
const clip = (w: Wipe, p: number, hz: boolean): React.CSSProperties => {
  if (p >= 1 || w === "cut") return {};
  if (w === "bars") { const m = `repeating-linear-gradient(to bottom, #000 0px, #000 ${(p * 192).toFixed(1)}px, transparent ${(p * 192).toFixed(1)}px, transparent 192px)`; return { WebkitMaskImage: m, maskImage: m }; }
  const c = w === "diag" ? `polygon(0 0, ${(p * 150).toFixed(2)}% 0, ${(p * 150 - 50).toFixed(2)}% 100%, 0 100%)`
    : w === "circle" ? (hz ? `circle(${(p * 1400).toFixed(0)}px at 1200px 540px)` : `circle(${(p * 2250).toFixed(0)}px at 540px 1100px)`)
    : w === "split" ? `inset(0 ${(50 - 50 * p).toFixed(2)}% 0 ${(50 - 50 * p).toFixed(2)}%)`
    : w === "up" ? `inset(${(100 - 100 * p).toFixed(2)}% 0 0 0)`
    : w === "side" ? `inset(0 0 0 ${(100 - 100 * p).toFixed(2)}%)`
    : `polygon(0 0, 100% 0, 100% ${(-22 + 124 * p).toFixed(2)}%, 50% ${(-2 + 124 * p).toFixed(2)}%, 0 ${(-22 + 124 * p).toFixed(2)}%)`;
  return { clipPath: c };
};
const Layer: React.FC<{ i: number; t: number; style?: React.CSSProperties }> = ({ i, t, style }) => {
  const [, Sc, th] = SHOTS[i];
  const hz = React.useContext(Hz);
  return (
    <AbsoluteFill style={{ background: th.bg, ...style }}>
      {th.dark && <AbsoluteFill style={{ background: hz ? "radial-gradient(38% 62% at 75% 50%, rgba(92,134,204,0.22) 0%, rgba(92,134,204,0) 100%)" : "radial-gradient(60% 42% at 50% 64%, rgba(92,134,204,0.22) 0%, rgba(92,134,204,0) 100%)" }} />}
      <Sc t={t} th={th} />
    </AbsoluteFill>
  );
};

export const Ventus: React.FC<{ horizontal?: boolean }> = ({ horizontal = false }) => {
  const t = interpolate(useCurrentFrame() / VEN_FPS, WARP.map((w) => w[0]), WARP.map((w) => w[1]));
  const i = shotAt(t);
  const [s, , , w] = SHOTS[i];
  const p = w === "cut" ? 1 : io(t, s, s + WD);
  return (
    <Hz.Provider value={horizontal}>
      <AbsoluteFill style={{ background: NAVY }}>
        {p < 1 && i > 0 && <Layer i={i - 1} t={t} />}
        <Layer i={i} t={t} style={clip(w, p, horizontal)} />
      </AbsoluteFill>
    </Hz.Provider>
  );
};

